import "./Sidebar.css";

function Sidebar() {
  return (
    <div className="sidebar">
      <h3>Fastcart</h3>
      <ul>
        <li>Dashboard</li>
        <li>Products</li>
        <li>Orders</li>
        <li className="active">Categories</li>
        

      </ul>
    </div>
  );
}

export default Sidebar;
